-- Spawn and script Deadmines (36) and Ragefire Chasm (389).
-- Remaps instance creature/gameobject GUIDs into a free SkyFire range.

SET @CGUID := 8200000;
SET @OGUID := 270000;

-- Remove any prior instance spawns on these maps.
DELETE ca FROM creature_addon ca INNER JOIN creature c ON ca.guid = c.guid WHERE c.map IN (36, 389);
DELETE FROM creature WHERE map IN (36, 389);
DELETE FROM gameobject WHERE map IN (36, 389);

